mapper.select:
SELECT status FROM sys_flow_event_delivery
WHERE event_id = #{eventId} AND tenant_id = #{tenantId} AND consumer_id = #{consumerId}
FOR UPDATE

mapper.update:
UPDATE sys_flow_event_delivery SET status = 'ACKNOWLEDGED', acknowledged_at = CURRENT_TIMESTAMP(3)
WHERE event_id = #{eventId} AND tenant_id = #{tenantId} AND consumer_id = #{consumerId}
  AND status = 'PENDING'

mapper.select:
SELECT event_id, tenant_id, consumer_id, attempt_count
FROM sys_flow_event_delivery
WHERE status = 'PENDING' AND next_attempt_at <= #{now}
  AND (claimed_until IS NULL OR claimed_until <= #{now})
ORDER BY next_attempt_at, event_id
LIMIT #{limit}

mapper.update:
UPDATE sys_flow_event_delivery
SET claim_id = #{claimId}, claimed_until = #{until}, attempt_count = attempt_count + 1
WHERE event_id = #{delivery.eventId} AND tenant_id = #{delivery.tenantId}
  AND consumer_id = #{delivery.consumerId} AND status = 'PENDING'
  AND attempt_count = #{delivery.attemptCount} AND next_attempt_at <= #{now}
  AND (claimed_until IS NULL OR claimed_until <= #{now})

UPDATE sys_flow_event_delivery
SET next_attempt_at = #{next}, last_error = #{error}, claim_id = NULL, claimed_until = NULL
WHERE event_id = #{identity.eventId} AND tenant_id = #{identity.tenantId}
  AND consumer_id = #{identity.consumerId} AND status = 'PENDING' AND claim_id = #{claimId}
